sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float shadowHue;
uniform float shadowSat;
uniform float highlightHue;
uniform float highlightSat;
uniform float balance;
uniform float strength;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 hsv2rgb(float3 c) {
    float3 p = abs(fract(float3(c.x) + float3(1.0, 0.6666667, 0.3333333)) * 6.0 - 3.0);
    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float l = luma(s);
    float edge = 0.5 + balance * 0.35;
    float sw = 1.0 - smoothstep(0.0, edge, l);
    float hw = smoothstep(edge, 1.0, l);
    float3 sc = hsv2rgb(float3(shadowHue / 360.0, 1.0, 1.0));
    float3 hc = hsv2rgb(float3(highlightHue / 360.0, 1.0, 1.0));
    float3 o = s + (sc - luma(sc)) * shadowSat * sw * strength + (hc - luma(hc)) * highlightSat * hw * strength;
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
